"""Controller-only server evaluation; hidden oracle never copied into review inputs."""
import argparse,json
from pathlib import Path
from tools.memo_blind_trial import prepare
from tools.memo_real_trial import NATIVE
from harness.delegation import Development,digest
from harness.qa import QA
from harness.qa_repair import execute_with_owner

def run(source,root):
 m=prepare(source,root,'implementation');rel='server/src/main/kotlin/trial/memo/server/Main.kt';p=root/rel
 old=p.read_text();a='Memo(UUID.randomUUID().toString(), body, Instant.now().toString())';b='Memo(UUID.randomUUID().toString(), body.take(20), Instant.now().toString())';assert old.count(a)==1;p.write_text(old.replace(a,b))
 oracle=root.parent/'agent-workflows'/(root.name+'-oracle.json');d=json.loads(oracle.read_text());d['injection']=[{'path':rel,'before_sha256':digest(source/rel),'after_sha256':digest(p),'replacement':b,'answer':'REQ-02 accepted text is truncated before storage/response.'}];oracle.write_text(json.dumps(d,ensure_ascii=False,indent=2))
 refs={'planning':'planning.md','design':'design/design.md','api':'api.md','policy':'policy.md'}
 m.register('MEMO-QUALITY','SERVER-TARGET','development','Memo API implementation review target','Server API only; not Web/mobile acceptance',[{'id':'SERVER-AC','required':True,'description':'Exact request-body preservation and API validation'}],list(refs.values())+['original-request.md'],max_attempts=1,work_type='HARNESS_BUILD',execution_scope='code_implementation',pipeline_stage='development')
 m.configure_development('SERVER-TARGET',refs,['server/src'],api_required=True,service_version='memo-trial-v1');m.ready('SERVER-TARGET');aid=m.begin('SERVER-TARGET','development',execution_mode='local_check')['agent_run_id'];m.submit('SERVER-TARGET',aid,[rel],'Imported actual implementation for independent API review, not a quality claim')
 m.register('MEMO-QUALITY','SERVER-REPAIR','development','Correct independent API QA findings','Only server/src; unchanged common/Web/policy/settings',[{'id':'SERVER-REPAIR-AC','required':True,'description':'Actual compile and API regression plus independent retest'}],list(refs.values())+['original-request.md'],max_attempts=2,work_type='HARNESS_BUILD',execution_scope='code_implementation',pipeline_stage='development');m.configure_development('SERVER-REPAIR',refs,['server/src'],api_required=True,service_version='memo-trial-v1')
 verifier=str(Path(__file__).resolve().with_name('memo_acceptance.py'));http=['rtk','proxy','python3','-B',verifier,'--project',str(root),'--port','18792','--expect-empty'];build=['rtk','proxy','python3','tools/build.py',':server:installDist']
 Development(root,m.run_id).configure('SERVER-REPAIR',[{'task_id':'SERVER-REPAIR-CHILD','area':'server','title':'Address independent memo API QA findings','goal':'Read immutable original request/API and current Server/common source. Independently correct actual API findings returned to the parent QA. Product edits only server/src. Exact policy unchanged. Implement correction, report verification NOT_RUN honestly if sandbox blocks Gradle; coordinator owns actual compile and API tests. Do not modify tests/contracts/root settings. COMPLETE means implementation completed; independent QA checks quality.','requirement_ids':['REQ-01','REQ-02','REQ-05'],'acceptance_ids':['SERVER-FIX'],'allowed_paths':['server/src'],'dependencies':[],'verification_commands':[build],'out_of_scope':['shared','web','design','original requests','build settings','Git commits'],'max_attempts':2}],{'evidence':['architecture.md'],'modules':{'server':['server/src']}},{p:'SERVER-REPAIR' for p in ('build.gradle.kts','settings.gradle.kts','gradle.properties')},[http],max_parallel=1,executable=NATIVE,timeout=600)
 # Build the exact submitted target before QA. No model result or expected answer injected.
 rc=m.logger.command(m.run_id,build,task_id='SERVER-TARGET',agent_run_id=aid,attempt_id=aid,command_kind='build');print('Target build exit',rc,flush=True)
 q=QA(root,m.run_id);q.configure('SERVER-QA','implementation','SERVER-TARGET',['original-request.md'],[{'id':'SERVER-EXACTNESS','required':True,'description':'Independent API-focused QA only. Inspect actual shared and server implementation against REQ-01/02/05: valid input boundaries, exact accepted-body preservation for long Unicode and multiline values, rejected requests do not insert, chronological save and refetch. Examine source yourself; do not modify product files or trust an author summary. If commands cannot run distinguish NOT_RUN from source findings. Record actionable findings with exact code_ref and baseline references. On retest directly verify prior issue IDs, do not simply repeat an owner claim. Web/mobile visual validation is outside this review.'}],commands=[http],max_attempts=2,repair_task_id='SERVER-REPAIR',executable=NATIVE,timeout=600)
 print(json.dumps(execute_with_owner(q,'SERVER-QA'),ensure_ascii=False,indent=2))
def resume(root):
 from tools.memo_real_trial import manager
 m=manager(root);build=['rtk','proxy','python3','tools/build.py',':server:installDist']
 review=m.begin('SERVER-TARGET','verification',review=True,execution_mode='local_check');aid=review['agent_run_id']
 rc=m.logger.command(m.run_id,build,task_id='SERVER-TARGET',agent_run_id=aid,attempt_id=aid,command_kind='build')
 proof=root/'.harness/target-build.md';proof.write_text('Actual target build exit '+str(rc)+'; API quality NOT_RUN until independent QA.');m.review('SERVER-TARGET',aid,[{'criterion_id':'SERVER-AC','result':'NOT_RUN','evidence':str(proof.relative_to(root))}],'Build is not API acceptance')
 verifier=str(Path(__file__).resolve().with_name('memo_acceptance.py'));http=['rtk','proxy','python3','-B',verifier,'--project',str(root),'--port','18792','--expect-empty']
 q=QA(root,m.run_id);q.configure('SERVER-QA','implementation','SERVER-TARGET',['original-request.md'],[{'id':'SERVER-EXACTNESS','required':True,'description':'Independently review actual common+server source against REQ-01/02/05. Verify input boundaries, exact accepted-body preservation for long Unicode and multiline values, invalid requests do not insert, chronological saved records and refetch. Do not modify product files or trust an author claim. Report actual code findings with exact code_ref and immutable basis, and honest NOT_RUN where commands cannot execute. Retest must explicitly verify earlier issue IDs. Web/mobile visual acceptance is outside this API-focused review.'}],commands=[http],max_attempts=2,repair_task_id='SERVER-REPAIR',executable=NATIVE,timeout=600)
 print(json.dumps(execute_with_owner(q,'SERVER-QA'),ensure_ascii=False,indent=2))
def evidence_review(root):
 import shutil
 from tools.memo_real_trial import manager
 m=manager(root);(root/'evidence').mkdir(exist_ok=True);shutil.copy2(root/'.worker-cache/e2e/result.json',root/'evidence/http-verified.json')
 q=QA(root,m.run_id);q.configure('SERVER-QA-EVIDENCE','retest','SERVER-TARGET',['original-request.md'],[
 {'id':'API-SOURCE','required':True,'description':'Directly inspect current actual shared/server source for REQ-01/02/05. Prior output snapshots are preserved history, not current code. Verify previous finding IDs against current source and explicitly list resolved IDs only if actually corrected.'},
 {'id':'API-ACTUAL-HTTP','required':True,'description':'Independently audit frozen evidence/http-verified.json from actual compiled Ktor process. Verify actual code_sha256 values against current files and inputs, all nine HTTP cases, process/exit/timestamp, real server save and GET and Unicode rejection/non-insertion. This criterion is review of actual independently executed HTTP evidence, not a claim that you personally reran Gradle inside the sandbox. Do not substitute an author summary. If raw evidence is incomplete/conflicting/stale report NOT_RUN/BLOCKED honestly. Evidence fields must be one actual qa-tools file path, not a sentence or semicolon-separated paths. Web/mobile acceptance is outside this review.'}],max_attempts=1,executable=NATIVE,timeout=600,context_files=['evidence/http-verified.json'])
 print(json.dumps(q.execute('SERVER-QA-EVIDENCE'),ensure_ascii=False,indent=2))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--source');p.add_argument('--root',required=True);p.add_argument('--resume',action='store_true');p.add_argument('--evidence-review',action='store_true');a=p.parse_args();root=Path(a.root).resolve();evidence_review(root) if a.evidence_review else resume(root) if a.resume else run(Path(a.source).resolve(),root)
